-- Marketplace administrator allowlist and RLS-gated moderation/dispute access.
create table public.marketplace_admins(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
alter table public.marketplace_admins enable row level security;alter table public.marketplace_admins force row level security;revoke all on public.marketplace_admins from anon,authenticated;grant select on public.marketplace_admins to authenticated;grant all on public.marketplace_admins to service_role;create policy marketplace_admin_self_read on public.marketplace_admins for select to authenticated using(user_id=(select auth.uid()));
create or replace function public.is_marketplace_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.marketplace_admins where user_id=(select auth.uid()))$$;revoke all on function public.is_marketplace_admin() from public,anon;grant execute on function public.is_marketplace_admin() to authenticated,service_role;
create policy marketplace_moderation_admin_read on public.marketplace_moderation_cases for select to authenticated using(public.is_marketplace_admin());create policy marketplace_moderation_admin_update on public.marketplace_moderation_cases for update to authenticated using(public.is_marketplace_admin()) with check(public.is_marketplace_admin());create policy marketplace_disputes_admin_read on public.marketplace_disputes for select to authenticated using(public.is_marketplace_admin());create policy marketplace_disputes_admin_update on public.marketplace_disputes for update to authenticated using(public.is_marketplace_admin()) with check(public.is_marketplace_admin());